package com.carrot.tmaprouteprobe;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.view.accessibility.*;import android.view.inputmethod.EditorInfo;import android.webkit.WebView;import android.widget.*;import org.json.*;import java.io.*;import java.nio.file.*;
/** Runs the user's magnifier -> input -> native result -> Naver flow. */
public final class KisaActualSearchRunner extends Instrumentation {
 volatile Activity current;JSONObject report=new JSONObject();File dir;String query="수학의힘 신검단캠퍼스";
 void check(boolean b,String s)throws Exception{if(!b)throw new Exception(s);}
 View tag(View v,String text){if(text.equals(v.getTag()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View r=tag(((ViewGroup)v).getChildAt(i),text);if(r!=null)return r;}return null;}
 AccessibilityNodeInfo text(AccessibilityNodeInfo v,String wanted){if(v==null)return null;if(wanted.contentEquals(v.getText()==null?"":v.getText()))return v;for(int i=0;i<v.getChildCount();i++){AccessibilityNodeInfo found=text(v.getChild(i),wanted);if(found!=null)return found;}return null;}
 void shot(String name)throws Exception{android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(dir,name))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 void tree(View view,JSONArray out)throws Exception{if(view instanceof WebView)out.put(new JSONObject().put("web",String.valueOf(((WebView)view).getUrl())));if(view.getTag()!=null)out.put(new JSONObject().put("tag",String.valueOf(view.getTag())).put("shown",view.isShown()));if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)tree(((ViewGroup)view).getChildAt(i),out);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();android.accessibilityservice.AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS|android.accessibilityservice.AccessibilityServiceInfo.FLAG_INCLUDE_NOT_IMPORTANT_VIEWS;getUiAutomation().setServiceInfo(info);dir=new File(c.getExternalFilesDir(null),"kisa_actual_search_probe");dir.mkdirs();Application application=(Application)c.getApplicationContext();application.registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){current=a;}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}});
  startActivitySync(c.getPackageManager().getLaunchIntentForPackage(c.getPackageName()).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(3000);check(current!=null,"Home missing");Activity home=current;runOnMainSync(()->{try{c.getClassLoader().loadClass("com.carrot.naverroute.HomeIdleBridge").getMethod("pause",Activity.class).invoke(null,home);}catch(Exception e){throw new RuntimeException(e);}home.findViewById(home.getResources().getIdentifier("button_safety_driving","id",home.getPackageName())).performClick();});Thread.sleep(2300);Activity navi=current;report.put("safe_drive_host",navi.getClass().getName());runOnMainSync(()->navi.findViewById(navi.getResources().getIdentifier("search_button","id",navi.getPackageName())).performClick());Thread.sleep(1000);
  AccessibilityNodeInfo label=null;for(int attempt=0;attempt<20&&label==null;attempt++){Thread.sleep(300);label=text(getUiAutomation().getRootInActiveWindow(),"장소 검색");}check(label!=null,"Magnifier search field missing");while(label!=null&&!label.isClickable())label=label.getParent();check(label!=null,"Search entry not clickable");label.performAction(AccessibilityNodeInfo.ACTION_CLICK);Thread.sleep(1700);Activity input=current;report.put("input_host",input.getClass().getName());runOnMainSync(()->{EditText edit=input.findViewById(input.getResources().getIdentifier("search_edit_text","id",input.getPackageName()));if(edit==null)throw new RuntimeException("Native input missing");edit.setText(query);edit.onEditorAction(EditorInfo.IME_ACTION_SEARCH);});Thread.sleep(6500);Activity results=current;report.put("result_host",results.getClass().getName());JSONArray views=new JSONArray();runOnMainSync(()->{try{tree(results.getWindow().getDecorView(),views);}catch(Exception e){throw new RuntimeException(e);}});report.put("result_views",views);View[] button={null};runOnMainSync(()->button[0]=tag(results.getWindow().getDecorView(),"carrot-naver-place-search"));report.put("naver_button_exists",button[0]!=null).put("naver_button_visible",button[0]!=null&&button[0].isShown());shot("magnifier-native-results.png");check(button[0]!=null&&button[0].isShown(),"Naver additional search missing after actual magnifier search");runOnMainSync(()->button[0].performClick());Thread.sleep(1500);shot("magnifier-naver-results.png");check(text(getUiAutomation().getRootInActiveWindow(),query)!=null,"Original query not reused");report.put("query_reused",true);
 }catch(Throwable e){while(e.getCause()!=null)e=e.getCause();try{report.put("error",e.toString());shot("failure.png");}catch(Exception ignored){}}try{Files.write(new File(dir,"report.json").toPath(),report.toString(2).getBytes("UTF-8"));}catch(Exception ignored){}result.putString("report",report.toString());finish(Activity.RESULT_OK,result);}
}
